import React, { useState, useEffect } from 'react';
import {
  Box,
  Paper,
  Typography,
  TextField,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  CircularProgress,
  Alert,
  Grid,
  Card,
  CardContent,
  CardHeader,
} from '@mui/material';
import { Home, Storage, BarChart } from '@mui/icons-material';

export const Dashboard = () => {
  const [stats, setStats] = useState({
    totalEvents: 0,
    activeConnections: 0,
    suspiciousActivity: 0,
    systemHealth: 'healthy'
  });
  const [trafficStats, setTrafficStats] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [hostId, setHostId] = useState('');

  useEffect(() => {
    const fetchDashboardData = async () => {
      setLoading(true);
      setError(null);
      
      try {
        // Получаем основную статистику
        const response = await fetch('/api/dashboard/stats');
        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }
        const dashboardData = await response.json();
        
        // Если указан hostId, получаем детальную статистику
        if (hostId) {
          const trafficResponse = await fetch(`/api/traffic/stats/host/${hostId}`);
          if (!trafficResponse.ok) {
            throw new Error(`HTTP error! status: ${trafficResponse.status}`);
          }
          const trafficData = await trafficResponse.json();
          setTrafficStats(trafficData);
        } else {
          setTrafficStats(null);
        }
        
        setStats(dashboardData);
      } catch (err) {
        setError(err.message);
        console.error('Error fetching dashboard data:', err);
      } finally {
        setLoading(false);
      }
    };

    const timer = setTimeout(() => {
      fetchDashboardData();
    }, 500);

    return () => clearTimeout(timer);
  }, [hostId]);

  return (
    <Box sx={{ p: 3 }}>
      <Typography variant="h4" gutterBottom>
        Обзор системы SIEM
      </Typography>

      {/* Поисковая строка */}
      <Paper sx={{ p: 2, mb: 3 }}>
        <TextField
          fullWidth
          label="Host ID"
          value={hostId}
          onChange={(e) => setHostId(e.target.value)}
          margin="normal"
          placeholder="Enter host identifier"
        />
      </Paper>

      {/* Общая статистика */}
      <Grid container spacing={3} sx={{ mb: 3 }}>
        <Grid item xs={12} sm={6} md={3}>
          <Card>
            <CardHeader>
                title={
                    <Typography variant="h6">
                        Всего событий
                    </Typography>
                }
            </CardHeader>
            <CardContent>
              <Typography variant="h6">{stats.totalEvents.toLocaleString()}</Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <Card>
            <CardHeader>
                title={
                    <Typography variant="h6">
                        Активных подключений
                    </Typography>
                }
            </CardHeader>
            <CardContent>
              <Typography variant="h6">{stats.activeConnections}</Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <Card>
            <CardHeader>
                title={
                    <Typography variant="h6">
                        Подозрительной активности
                    </Typography>
                }
            </CardHeader>
            <CardContent>
              <Typography variant="h6">{stats.suspiciousActivity}</Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <Card>
            <CardHeader>
                title={
                    <Typography variant="h6">
                        Статус системы
                    </Typography>
                }
            </CardHeader>
            <CardContent>
              <Typography variant="h6">
                {stats.systemHealth === 'healthy' ? '✅ Здоровая' : '⚠️ Проблемы'}
              </Typography>
            </CardContent>
          </Card>
        </Grid>
      </Grid>

      {/* Детальная статистика */}
      {hostId && (
        <Grid container spacing={3} sx={{ mb: 3 }}>
          <Grid item xs={12}>
            <Card>
              <CardHeader>
                title={
                    <Typography variant="h6">
                        Детальная статистика трафика
                    </Typography>
                }
              </CardHeader>
              <CardContent>
                {trafficStats && (
                  <Table>
                    <TableHead>
                      <TableRow>
                        <TableCell>Метрика</TableCell>
                        <TableCell>Значение</TableCell>
                      </TableRow>
                    </TableHead>
                    <TableBody>
                      <TableRow>
                        <TableCell>Общий трафик</TableCell>
                        <TableCell>
                          {trafficStats.total_bytes_sent} bytes sent / {trafficStats.total_bytes_recv} bytes received
                        </TableCell>
                      </TableRow>
                      <TableRow>
                        <TableCell>Протоколы</TableCell>
                        <TableCell>
                          {Object.entries(trafficStats.by_protocol || {}).map(([protocol, count]) => 
                            `${protocol}: ${count}`
                          ).join(', ')}
                        </TableCell>
                      </TableRow>
                    </TableBody>
                  </Table>
                )}
              </CardContent>
            </Card>
          </Grid>
        </Grid>
      )}

      {/* Карточки быстрого доступа */}
      <Grid container spacing={2}>
        <Grid item xs={12} sm={4}>
          <Card>
            <CardContent sx={{ pt: 2 }}>
              <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
                <Home sx={{ fontSize: 48, mb: 2 }} />
                <Typography variant="subtitle1">Обзор</Typography>
              </Box>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} sm={4}>
          <Card>
            <CardContent sx={{ pt: 2 }}>
              <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
                <BarChart sx={{ fontSize: 48, mb: 2 }} />
                <Typography variant="subtitle1">Статистика</Typography>
              </Box>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} sm={4}>
          <Card>
            <CardContent sx={{ pt: 2 }}>
              <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
                <Storage sx={{ fontSize: 48, mb: 2 }} />
                <Typography variant="subtitle1">Артефакты</Typography>
              </Box>
            </CardContent>
          </Card>
        </Grid>
      </Grid>

      {/* Обработка загрузки и ошибок */}
      {error && (
        <Alert severity="error" sx={{ mt: 2 }}>
          {error}
        </Alert>
      )}
      {loading && (
        <Box display="flex" justifyContent="center" p={4}>
          <CircularProgress />
        </Box>
      )}
    </Box>
  );
};
